entries[435902] = { ["name"] = "Formel: Brust - Vergelter", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine Brustrüstung dauerhaft so verzaubert, dass sie bei eingehenden Nahkampfangriffen 9 Schaden auf den Angreifer zurückwirft." }
entries[435903] = { ["name"] = "Brust - Vergelter", ["text"] = "Wirken in 5 sek.\nBenötigt Brust, Brust\nTools: Runenverzierte Goldrute\nReagenzien:\nKleiner strahlender Splitter , Traumstaub (2)\nLehrt Euch, wie man eine Brustrüstung dauerhaft so verzaubert, dass sie bei eingehenden Nahkampfangriffen 9 Schaden auf den Angreifer zurückwirft." }
entries[435904] = { ["name"] = "Leuchtende Gneuro-verkettete Gugel", ["text"] = "Wirken in 45 sek.\nReagenzien:\nHyperleitender Arkanfaden , Geschmeidiger dicker Balg (5), Seidenfaden (2), Schwach leuchtendes Leder (5)\nLeuchtende Gneuro-verkettete Gugel\nWird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+14 Beweglichkeit\n+14 Ausdauer\nHaltbarkeit 70 / 70\n40\nBenötigt Lederverarbeitung\n(225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +3 Waffenschaden.\nBenutzen: Belegt Euch mit 'Gneurologischer Schock', was Euch sofort 343 bis 757 Schaden zufügt, aber auch Eure Nahkampf- und Distanzangriffe 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)" }
entries[435905] = { ["name"] = "Muster: Leuchtende Gneuro-verkettete Gugel", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine leuchtende Gneuro-verkettete Gugel herstellt." }
entries[435906] = { ["name"] = "Reflektierender Echtsilbergehirnkäfig", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden (2), Polierte Echtsilberzahnräder\nReflektierender Echtsilbergehirnkäfig\nWird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 100 / 100\n40\nBenötigt Schmiedekunst\n(225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt verstärkte Willenskraft, die 10 Sek. lang Stille- und Unterbrechungseffekte sowie Zauberverzögerungen verhindert. (10 Min Abklingzeit)" }
entries[435907] = { ["name"] = "Pläne: Reflektierender Echtsilbergehirnkäfig", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man einen reflektierenden Echtsilbergehirnkäfig herstellt." }
entries[435908] = { ["name"] = "Gehärteter Interferenzen-negierender Helm", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (25), Echtsilberplatten mit geringer Grundstrahlung (4), Hyperleitender Arkanfaden , Schwach leuchtendes Leder (2)\nGehärteter Interferenzen-negierender Helm\nWird beim Aufheben gebunden\nKopf Platte\n426 Rüstung\n+20 Stärke\n+14 Ausdauer\nHaltbarkeit 100 / 100\n40\nBenötigt Schmiedekunst\n(225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Gewährt höchste Konzentration, die 10 Sek. lang die Bewegungsgeschwindigkeit um 20% verringert, aber währenddessen Euren Zauberwiderstand gegen alle Magiearten um 50 sowie das Angriffstempo im Nahkampf um 20% erhöht. (10 Min Abklingzeit)\n\"Schützt Euer Hirn garantiert vor allen Bedrohungen, physischen wie anderen!\"" }
entries[435909] = { ["name"] = "Pläne: Gehärteter Interferenzen-negierender Helm", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man einen gehärteten Interferenzen-negierenden Helm herstellt." }
