entries[435949] = { ["name"] = "Leuchtende hyperleitende Schuppenkappe", ["text"] = "Wirken in 45 sek.\nReagenzien:\nEchtsilberplatten mit geringer Grundstrahlung , Dicke Murlocschuppe (10), Schwach leuchtendes Leder (5), Isolierendes Gniodin\nLeuchtende hyperleitende Schuppenkappe\nWird beim Aufheben gebunden\nKopf Kette\n242 Rüstung\n+14 Ausdauer\n+15 Intelligenz\nHaltbarkeit 85 / 85\n40\nBenötigt Lederverarbeitung\n(225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Belegt Euch mit 'Hyperleitender Schock', was Euch sofort 312 bis 688 Schaden zufügt, aber auch Euer Zauberwirken 10 Sek. lang um 20% beschleunigt. (10 Min Abklingzeit)" }
entries[435950] = { ["name"] = "Muster: Leuchtende hyperleitende Schuppenkappe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine leuchtende hyperleitende Schuppenkappe herstellt." }
entries[435951] = { ["name"] = "Gneuro-leitende Kapuze des Kanalisierers", ["text"] = "Wirken in 45 sek.\nReagenzien:\nIsolierendes Gniodin , Geschmeidiger dicker Balg (5), Schwach leuchtendes Leder (5), Hyperleitender Arkanfaden\nGneuro-leitende Kapuze des Kanalisierers\nWird beim Aufheben gebunden\nKopf Leder\n118 Rüstung\n+11 Ausdauer\n+12 Intelligenz\n+11 Willenskraft\nHaltbarkeit 70 / 70\n40\nBenötigt Lederverarbeitung\n(225)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nBenutzen: Gewährt 'Gneuromantische Meditation', wodurch 20 Sek. lang 100% Eurer Manaregeneration während des Zauberwirkens erhalten bleibt und der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 50 erhöht werden. (10 Min Abklingzeit)" }
entries[435952] = { ["name"] = "Muster: Gneuro-leitende Kapuze des Kanalisierers", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine Gneuro-leitende Kapuze des Kanalisierers herstellt." }
entries[435953] = { ["name"] = "Strahlungsresistente Schuppenkapuze", ["text"] = "Wirken in 45 sek.\nReagenzien:\nEchtsilberplatten mit geringer Grundstrahlung , Geschmeidiger dicker Balg (5), Schwach leuchtendes Leder (5), Isolierendes Gniodin\nStrahlungsresistente Schuppenkapuze\nWird beim Aufheben gebunden\nKopf Kette\n342 Rüstung\n+10 Ausdauer\n+10 Intelligenz\nHaltbarkeit 85 / 85\n40\nBenötigt Lederverarbeitung\n(225)\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: +32 Angriffskraft.\nBenutzen: Aktiviert die Protokolle zur Strahlungsabschwächung in diesem Helm, die sofort alle aktiven Gifteffekte von Euch entfernen und Euch 3 Sek. lang immun gegen jeglichen Naturschaden machen. (10 Min Abklingzeit)" }
entries[435954] = { ["name"] = "Muster: Strahlungsresistente Schuppenkapuze", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine strahlungsresistente Schuppenkapuze herstellt." }
entries[435956] = { ["name"] = "Polierte Echtsilberzahnräder", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtsilberbarren , Haufen aus stumpfen Zahnrädern (5)\nPolierte Echtsilberzahnräder" }
entries[435957] = { ["name"] = "Bauplan: Polierte Echtsilberzahnräder", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man polierte Echtsilberzahnräder herstellt." }
entries[435958] = { ["name"] = "Wirbelnder Echtsilberzahnradschild", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtsilberplatten mit geringer Grundstrahlung (3), Polierte Echtsilberzahnräder (5), Schwach leuchtendes Leder (2), Mithrilgehäuse (2), Gyrochronatom (2), Mithrilbarren (15)\nWirbelnder Echtsilberzahnradschild\nWird beim Aufheben gebunden\nSchildhand Schild\n1760 Rüstung\n29 Blocken\n+9 Stärke\n+10 Ausdauer\nHaltbarkeit 120 / 120\n40\nBenötigt Ingenieurskunst\n(225)\nAnlegen: Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 1%.\nAnlegen: Bei erfolgreichem Blocken fügen die wirbelnden rasiermesserscharfen Zahnräder dieses Schilds dem Angreifer 5 bis 10 körperlichen Schaden und dem Träger 2 bis 10 körperlichen Schaden zu.\n\"Die rotierenden Schneiden dieses Schilds sind überraschend scharfkantig. Er wirkt genauso gefährlich für den Träger wie für den Angreifer.\"" }
entries[435959] = { ["name"] = "Bauplan: Wirbelnder Echtsilberzahnradschild", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man einen wirbelnden Echtsilberzahnradschild herstellt." }
entries[435960] = { ["name"] = "Hyperleitendes Goldnetz", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nPolierte Echtsilberzahnräder (3), Hyperleitender Arkanfaden (3), Schwach leuchtendes Leder , Goldbarren (10)\nHyperleitendes Goldnetz\nWird beim Aufheben gebunden\nTaille Stoff\n40 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\n40\nBenötigt Ingenieurskunst\n(225)\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nBenutzen: Ihr zieht eine hyperleitende Münze aus Eurem Gürtel und werft sie hoch. Kopf: Erhöht Eure kritische Trefferchance mit allen Zaubern und Angriffen 30 Sek. lang um 3%. Zahl: Erhöht Eure Bewegungsgeschwindigkeit 30 Sek. lang um 10%. (15 Min Abklingzeit)\n\"Dieser Gürtel klickt leise, während Ihr Euch bewegt.\"" }
entries[435961] = { ["name"] = "Bauplan: Hyperleitendes Goldnetz", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man ein hyperleitendes Goldnetz herstellt." }
entries[435962] = { ["name"] = "Buchband der Erlösung" }
entries[435963] = { ["name"] = "Hoch wirksame Strahlungsbombe", ["text"] = "25 Meter Reichweite\nWirken in 1 sek.\nVerursacht im Explosionsradius 150 bis 250 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 25 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%." }
entries[435964] = { ["name"] = "Hoch wirksame Strahlungsbombe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nRobustes Sprengpulver , Ablagerung von Gnomeregan , Mithrilbarren (2)\nHoch wirksame Strahlungsbombe\n(2)\n35\nBenötigt Ingenieurskunst\n(200)\nBenutzen: Verursacht im Explosionsradius 150 bis 250 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 25 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen bis Abbruch lang um 25%. (1 Min Abklingzeit)" }
entries[435965] = { ["name"] = "Bauplan: Hoch wirksame Strahlungsbombe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine hoch wirksame Strahlungsbombe herstellt." }
entries[435966] = { ["name"] = "EZ-Thro-Strahlungsbombe", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nRobustes Sprengpulver (2), Ablagerung von Gnomeregan , Mithrilbarren (2)\nEZ-Thro-Strahlungsbombe\n(2)\n40\nBenutzen: Verursacht im Explosionsradius 112 bis 188 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 10 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%. (1 Min Abklingzeit)\n\"Eine abgeschwächte, aber nicht weniger tödliche Version ihres komplexeren Gegenstücks, für diejenigen, denen zwar die Kompetenz fehlt, die aber dafür Zuversicht im Überfluss haben.\"" }
entries[435967] = { ["name"] = "Bauplan: EZ-Thro-Strahlungsbombe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man eine EZ-Thro-Strahlungsbombe herstellt." }
entries[435968] = { ["name"] = "EZ-Thro-Strahlungsbombe", ["text"] = "25 Meter Reichweite\nWirken in 1.5 sek.\nVerursacht im Explosionsradius 112 bis 188 Feuerschaden und zusätzlich 10 Sek. lang alle 2 Sek. 10 Naturschaden. Verringert außerdem die Bewegungsgeschwindigkeit von betroffenen Zielen 10 Sek. lang um 25%." }
entries[435969] = { ["name"] = "Isolierendes Gniodin", ["text"] = "Wirken in 3 sek.\nReagenzien:\nVerbleite Phiole , Kiste mit besudelter Gniodin-Lösung (5)\nIsolierendes Gniodin" }
