entries[437327] = { ["name"] = "Aufgeladene Inspiration", ["text"] = "Sofort\nIhr macht Euch die latente Arkanenergie in der Umgebungsluft zunutze und erhaltet 'Aufgeladene Inspiration', was 12 Sek. lang die Manakosten aller Zauber um 50% verringert und ihren verursachten Schaden und die durch sie hervorgerufene Heilung um bis zu 50 erhöht." }
