entries[437353] = { ["name"] = "Rüstungsfraß", ["text"] = "100 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde atmet eine Welle korrosiver Magie auf ein Ziel, fügt diesem 1140 bis 1260 Naturschaden zu und verringert dessen Rüstung 20 Sek. lang um 33%." }
