entries[440792] = { ["name"] = "Umhang prägen - Rechtschaffene Vergeltung", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune 'Rechtschaffene Vergeltung':\n\nWenn Eure Zauber 'Richturteil', 'Kreuzfahrerstoß' oder 'Göttlicher Sturm' einen kritischen Treffer erzielen, erleidet Euer Ziel im Verlauf von bis Abbruch 30% zusätzlichen Schaden." }
