entries[440802] = { ["name"] = "Gefrorene Kugel", ["text"] = "11% von Grundmana 40 Meter Reichweite\nSofort 1 min Abklingzeit\nSchleudert eine Kugel aus wirbelndem Eis, die sich im Verlauf von 16 Sek. schnell nach vorne bewegt. Während sie sich bewegt, verursacht die Kugel alle 1 Sek. [Quellwert] Frostschaden und belegt alle Gegner, durch die sie sich bewegt, mit 'Kühlung' und verringert ihre Bewegungsgeschwindigkeit um 30%. Sobald sie einem Gegner zum ersten Mal Schaden zufügt, verlangsamt sie ihre Bewegung und hat eine Chance von 100%, die Rune 'Eisige Finger' auszulösen.", ["unresolvedValues"] = true }
