entries[440858] = { ["name"] = "Umhang prägen - Gefrorene Kugel", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune\n'Gefrorene Kugel':\n\nSchleudert eine Kugel aus wirbelndem Eis, die sich im Verlauf von 16 Sek. schnell nach vorne bewegt. Während sie sich bewegt, verursacht die Kugel alle 1 Sek. [Quellwert] Frostschaden und belegt alle Gegner, durch die sie sich bewegt, mit 'Kühlung' und verringert ihre Bewegungsgeschwindigkeit um 30%. Sobald sie einem Gegner zum ersten Mal Schaden zufügt, verlangsamt sie ihre Bewegung und hat eine Chance von 100%, die Rune 'Eisige Finger' auszulösen.", ["unresolvedValues"] = true }
entries[440859] = { ["name"] = "Gefrorene Kugel", ["text"] = "Erhaltet die Fähigkeit 'Gefrorene Kugel':\n\nSchleudert eine Kugel aus wirbelndem Eis, die sich im Verlauf von 16 Sek. schnell nach vorne bewegt. Während sie sich bewegt, verursacht die Kugel alle 1 Sek. [Quellwert] Frostschaden und belegt alle Gegner, durch die sie sich bewegt, mit 'Kühlung' und verringert ihre Bewegungsgeschwindigkeit um 30%. Sobald sie einem Gegner zum ersten Mal Schaden zufügt, verlangsamt sie ihre Bewegung und hat eine Chance von 100%, die Rune 'Eisige Finger' auszulösen.", ["unresolvedValues"] = true }
entries[440870] = { ["name"] = "Dezimierung", ["text"] = "Euer Zauber 'Seelenfeuer' hat keine Abklingzeit mehr. Wenn Ihr Eure Zauber 'Schattenblitz', 'Schattenspalten', 'Verbrennen' oder 'Seelenfeuer' auf ein Ziel wirkt, das 35% Gesundheit oder weniger besitzt, wird die Zauberzeit von 'Seelenfeuer' 10 Sek. lang um 40% verringert. Wenn Ihr 'Seelenfeuer' einsetzt, während Ihr unter dem Effekt von 'Dezimierung' steht, kostet der Zauber keinen Seelensplitter." }
