entries[440882] = { ["name"] = "Höllische Rüstung", ["text"] = "3% von Grundmana\nSofort 1 min Abklingzeit\nEuer Geist wird von dämonischer Energie erfüllt, was Euren sämtlichen erlittenen magischen Schaden um einen Prozentsatz verringert, der 60% Eurer körperlichen Schadensverringerung durch Rüstung entspricht. Hält 10 Sek. lang an." }
entries[440892] = { ["name"] = "Mal des Chaos", ["text"] = "Mit Ausnahme von 'Fluch der Schatten' und 'Fluch der Elemente' belegen all Eure Flüche das Ziel nun mit 'Mal des Chaos', wodurch dessen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um [Max(Min( 56 + 19, 75), 27)] verringert und sämtlicher erlittener Zauberschaden dieser Magiearten um [Max(Min(( 56 - 8) * 0.125 + 4, 10), 4)]% erhöht wird, solange der Fluch andauert." }
